-- =========================================================================
-- DANASEA — SCRIPT SEED TOÀN DIỆN DỮ LIỆU DEMO CHUẨN TỪ DATABASE_DEMO
-- Nạp đầy đủ 12 Danh mục, 12 Users, 9 Vendors (APPROVED),
-- 24 Services (100% PUBLISHED), 33 Options, 72 Images (Cloudinary CDN),
-- và Slots hoạt động thực tế cho Hôm nay, Ngày mai, Ngày kia.
-- Chạy lệnh: Get-Content docs/seed_database_demo.sql -Raw | docker exec -i pbl6-postgres-1 psql -U danasea_user -d danasea_db
-- =========================================================================

BEGIN;
SET client_encoding = 'UTF8';

-- 1. BẢNG CATEGORIES (12 Danh mục trải nghiệm)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, slug = EXCLUDED.slug, is_active = TRUE, requires_safety_cert = EXCLUDED.requires_safety_cert, updated_at = NOW();

-- 2. BẢNG USERS (12 Tài khoản demo: 1 Admin, 9 Vendor, 2 Customer - Mật khẩu: password123)
ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, role = EXCLUDED.role, password_hash = EXCLUDED.password_hash, is_locked = FALSE, is_email_verified = TRUE, updated_at = NOW();

-- 3. BẢNG VENDORS (9 Nhà cung cấp - Kích hoạt APPROVED 100%)
ON CONFLICT (id) DO UPDATE SET verification_status = 'APPROVED', verified_at = NOW(), business_name = EXCLUDED.business_name, updated_at = NOW();

-- 4. BẢNG VENDOR_DOCUMENTS (18 Hồ sơ pháp lý - Trạng thái APPROVED)
ON CONFLICT (id) DO UPDATE SET status = 'APPROVED', reviewed_at = NOW(), file_url = EXCLUDED.file_url, updated_at = NOW();

-- 5. BẢNG SERVICES (24 Trải nghiệm biển Đà Nẵng - Trạng thái PUBLISHED)
ON CONFLICT (id) DO UPDATE SET status = 'PUBLISHED', price = EXCLUDED.price, name = EXCLUDED.name, description = EXCLUDED.description, location_name = EXCLUDED.location_name, address = EXCLUDED.address, waiver_content = EXCLUDED.waiver_content, waiver_content_en = EXCLUDED.waiver_content_en, waiver_required = EXCLUDED.waiver_required, updated_at = NOW();

-- 6. BẢNG SERVICE_OPTIONS (33 Gói dịch vụ chi tiết)
ON CONFLICT (id) DO UPDATE SET status = 'ACTIVE', price = EXCLUDED.price, name = EXCLUDED.name, benefits = EXCLUDED.benefits, updated_at = NOW();

-- 7. BẢNG SERVICE_SLOTS (Khung giờ trải nghiệm thực tế hôm nay & những ngày tới)
ON CONFLICT (id) DO UPDATE SET status = 'OPEN', date = EXCLUDED.date, start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time, updated_at = NOW();

-- 8. BẢNG SERVICE_IMAGES (72 Ảnh Cloudinary CDN sắc nét)
ON CONFLICT (id) DO UPDATE SET url = EXCLUDED.url, sort_order = EXCLUDED.sort_order, updated_at = NOW();

-- 9. BẢNG SERVICE_SAFETY_DOCUMENTS (24 Hồ sơ an toàn - Trạng thái APPROVED)
ON CONFLICT (id) DO UPDATE SET status = 'APPROVED', reviewed_at = NOW(), file_url = EXCLUDED.file_url, updated_at = NOW();

COMMIT;

-- Kiểm tra kết quả tổng hợp:
SELECT 'Categories' AS table_name, count(*) AS total FROM categories UNION ALL
SELECT 'Users', count(*) FROM users UNION ALL
SELECT 'Vendors (APPROVED)', count(*) FROM vendors WHERE verification_status = 'APPROVED' UNION ALL
SELECT 'Services (PUBLISHED)', count(*) FROM services WHERE status = 'PUBLISHED' UNION ALL
SELECT 'Service Options (ACTIVE)', count(*) FROM service_options WHERE status = 'ACTIVE' UNION ALL
SELECT 'Service Slots (OPEN)', count(*) FROM service_slots WHERE status = 'OPEN' UNION ALL
SELECT 'Service Images (Cloudinary)', count(*) FROM service_images WHERE url LIKE '%cloudinary%';